#include <iostream>

int main() {
    int pisteet = 72;
    if (pisteet >= 90) {
        std::cout << "Erinomainen\n";
    } else if (pisteet >= 50) {
        std::cout << "Hyväksytty\n";
    } else {
        std::cout << "Hylätty\n";
    }
    return 0;
}

#include <iostream>

int main() {
    int paiva = 1;
    switch (paiva) {
        case 1:
            std::cout << "Maanantai\n";
        case 2:
            std::cout << "Tiistai\n";
            break;
        default:
            std::cout << "Muu\n";
    }
    return 0;
}

